begin;
create function pg_temp.q_assert(ok boolean,label text) returns void language plpgsql as $$begin
 if ok is distinct from true then raise exception 'Quality assertion: %',label;end if;raise notice 'PASS %',label;
end$$;
create function pg_temp.q_error(statement text,expected text) returns void language plpgsql as $$begin
 begin execute statement;set constraints quality_entry_weight_check immediate;set constraints quality_entry_weight_check deferred;exception when others then if sqlerrm=expected then raise notice 'PASS blocked %',expected;return;end if;
 raise exception 'Expected %, got %',expected,sqlerrm;end;raise exception 'Expected failure %',expected;
end$$;
create function pg_temp.q_source(f uuid,e uuid) returns uuid language plpgsql as $$declare s uuid;begin
 select id into s from public.finished_goods_sources where factory_id=f and entry_id=e;
 perform public.source_stock_command(f,'identify',jsonb_build_object('source',s,'quantity','100','label','COUNTED-'||s::text,'physically_identified',true),'[]',gen_random_uuid());return s;
end$$;
do $$declare x quality_test.fixtures;y quality_test.fixtures;z quality_test.fixtures;s uuid;s2 uuid;r uuid;other uuid;q uuid;q2 uuid;retry uuid;p jsonb;lot uuid;normal_lot uuid;mr uuid;rev integer;entry uuid;finish timestamptz;shift uuid;detail jsonb;actor uuid;bad uuid;so uuid;sl uuid;begin
 perform quality_test.make_fixture('quality-meter','meter',0.35,100);select * into x from quality_test.fixtures where name='quality-meter';
 s:=pg_temp.q_source(x.factory_id,x.entry_id);select id into r from public.quality_reasons where factory_id=x.factory_id and name='Dimensional defect';
 retry:=gen_random_uuid();p:=jsonb_build_object('source',s,'quantity','20','reason',r,'disposition','SCRAP','actual_scrap_kg','7.00','physically_identified',true);
 q:=public.quality_command(x.factory_id,'reject',p,retry);
 perform pg_temp.q_assert((select default_scrap_kg=7 and actual_scrap_kg=7 and not weight_overridden from public.quality_rejections where id=q),'20m at .35 -> exact 7kg');
 perform pg_temp.q_assert(public.quality_command(x.factory_id,'reject',p,retry)=q,'Quality retry returns same rejection');
 perform pg_temp.q_assert((select on_hand=80 from public.finished_goods_balances where factory_id=x.factory_id) and (select count(*)=1 from public.quality_rejections where factory_id=x.factory_id),'stock and kg event exactly once');
 perform pg_temp.q_assert((select good_quantity=100 and accepted_good_quantity=80 from public.production_orders where id=x.item_id) and (select effective_good=100 and effective_scrap_kg=0 from public.production_entries where id=x.entry_id),'gross production and Production Scrap preserved');
 q2:=public.quality_command(x.factory_id,'reject',p||jsonb_build_object('actual_scrap_kg','7.40','note','Weighed on scale'),gen_random_uuid());
 perform pg_temp.q_assert((select default_scrap_kg=7 and actual_scrap_kg=7.4 and weight_overridden and note='Weighed on scale' from public.quality_rejections where id=q2),'actual kg override independent of production quantity');
 perform pg_temp.q_assert((select sum(actual_scrap_kg)=14.4 from public.quality_rejections where factory_id=x.factory_id),'Quality actual kg summed once');
 perform public.quality_command(x.factory_id,'reverse',jsonb_build_object('rejection',q2,'physically_present',true,'reason','Erroneous duplicate physical count, goods still labelled'),gen_random_uuid());
 perform pg_temp.q_assert((select on_hand=80 from public.finished_goods_balances where factory_id=x.factory_id) and exists(select 1 from public.quality_rejections where id=q2) and exists(select 1 from public.quality_reversals where rejection_id=q2),'traceable reversal retains original and restores exact stock');
 perform pg_temp.q_assert(public.quality_read(x.factory_id,'{"mode":"board"}')->>'quality_scrap_kg'='7.00','net additional Quality kg excludes reversal and retains immutable event');
 q2:=public.quality_command(x.factory_id,'reject',p||jsonb_build_object('quantity','1.125','actual_scrap_kg','0.39375'),gen_random_uuid());
 perform pg_temp.q_assert((select default_scrap_kg=0.39375 and quantity=1.125 from public.quality_rejections where id=q2),'fractional meters conserve exact decimal mass');
 perform pg_temp.q_error(format('select public.quality_command(%L,''reject'',%L::jsonb,gen_random_uuid())',x.factory_id,(p||jsonb_build_object('quantity','1000'))::text),'quality_unavailable');
 perform pg_temp.q_assert((select count(*)=3 from public.quality_rejections where factory_id=x.factory_id),'failed rejection rolls back event, stock and notification');
 detail:=public.quality_read(x.factory_id,jsonb_build_object('mode','detail','rejection',q));
 perform pg_temp.q_assert(detail->>'item_id'=x.item_id::text and detail->>'product_id'=x.product_id::text and detail->>'line_id'=x.line_id::text and detail->'notification'->>'id'=q::text,'notification deep link has exact item/product/line and recorded shift');
 perform public.quality_command(x.factory_id,'acknowledge',jsonb_build_object('rejection',q),gen_random_uuid());
 perform pg_temp.q_assert((select status='ACKNOWLEDGED' from public.quality_notifications where id=q),'persistent notification acknowledgment');
 perform pg_temp.q_error(format('select public.quality_command(%L,''resolve'',%L::jsonb,gen_random_uuid())',x.factory_id,jsonb_build_object('rejection',q)::text),'quality_shortfall');
 perform public.quality_command(x.factory_id,'reason',jsonb_build_object('id',r,'name','Renamed dimensional issue','name_ar','عيب الأبعاد','active',false),gen_random_uuid());
 perform pg_temp.q_assert((select reason='Dimensional defect' from public.quality_rejections where id=q),'reason snapshot survives rename and archive');
 select id into other from public.quality_reasons where factory_id=x.factory_id and is_other;
 q2:=public.quality_command(x.factory_id,'reject',p||jsonb_build_object('reason',other,'quantity','2','actual_scrap_kg','0.7','description','Socket alignment','approve_reason',true),gen_random_uuid());
 perform pg_temp.q_assert(exists(select 1 from public.quality_reasons where factory_id=x.factory_id and name='Socket alignment'),'Other can create approved reusable reason');
 perform pg_temp.q_error(format('select public.quality_command(%L,''reject'',%L::jsonb,gen_random_uuid())',x.factory_id,(p||jsonb_build_object('reason',other,'description','Socket alignment','approve_reason',true))::text),'quality_duplicate_reason');
 perform quality_test.make_fixture('quality-piece','piece',0.25,100);select * into y from quality_test.fixtures where name='quality-piece';
 s2:=pg_temp.q_source(y.factory_id,y.entry_id);select id into r from public.quality_reasons where factory_id=y.factory_id and not is_other limit 1;
 p:=jsonb_build_object('source',s2,'quantity','10','reason',r,'disposition','SCRAP','actual_scrap_kg','2.50','physically_identified',true);
 q:=public.quality_command(y.factory_id,'reject',p,gen_random_uuid());
 perform pg_temp.q_assert((select default_scrap_kg=2.5 and actual_scrap_kg=2.5 from public.quality_rejections where id=q),'10 pieces at .25 -> 2.50kg');
 q:=public.quality_command(y.factory_id,'reject',p||jsonb_build_object('actual_scrap_kg','2.70'),gen_random_uuid());
 perform pg_temp.q_assert((select default_scrap_kg=2.5 and actual_scrap_kg=2.7 and weight_overridden from public.quality_rejections where id=q),'piece actual 2.70kg override');
 perform pg_temp.q_error(format('select public.quality_command(%L,''reject'',%L::jsonb,gen_random_uuid())',y.factory_id,(p||jsonb_build_object('quantity','0.5'))::text),'quality_quantity');
 perform quality_test.make_fixture('quality-missing','meter',null,100);select * into z from quality_test.fixtures where name='quality-missing';
 s2:=pg_temp.q_source(z.factory_id,z.entry_id);select id into r from public.quality_reasons where factory_id=z.factory_id and not is_other limit 1;
 p:=jsonb_build_object('source',s2,'quantity','2','reason',r,'disposition','SCRAP','physically_identified',true);
 perform pg_temp.q_error(format('select public.quality_command(%L,''reject'',%L::jsonb,gen_random_uuid())',z.factory_id,p::text),'quality_weight');
 q:=public.quality_command(z.factory_id,'reject',p||jsonb_build_object('actual_scrap_kg','0.8'),gen_random_uuid());
 perform pg_temp.q_assert((select default_scrap_kg is null and weight_kg_per_unit is null and actual_scrap_kg=.8 from public.quality_rejections where id=q),'missing weight requires explicit manual positive kg');
 perform quality_test.make_fixture('quality-rework','piece',0.25,100,5);select * into x from quality_test.fixtures where name='quality-rework';
 s:=pg_temp.q_source(x.factory_id,x.entry_id);select id into r from public.quality_reasons where factory_id=x.factory_id and not is_other limit 1;
 perform public.finish_product_item(x.factory_id,x.item_id);select actual_finish into finish from public.production_orders where id=x.item_id;
 q:=public.quality_command(x.factory_id,'reject',jsonb_build_object('source',s,'quantity','10','reason',r,'disposition','REWORK','physically_identified',true),gen_random_uuid());
 select lot_id into lot from public.quality_rejections where id=q;
 select id into normal_lot from public.unfinished_lots where source_entry_id=x.entry_id and quality_rejection_id is null;
 perform pg_temp.q_assert((select quantity_available=10 and warehouse_quantity=10 and reserved_quality_rejection_id=q from public.unfinished_lots where id=lot),'rejection creates reserved stored WIP');
 perform pg_temp.q_assert((select actual_scrap_kg is null from public.quality_rejections where id=q) and (select accepted_good_quantity=90 from public.production_orders where id=x.item_id),'Rework changes acceptance without adding Scrap kg');
 perform public.correct_lean_production(x.factory_id,jsonb_build_object('entry',x.entry_id,'good',100,'discarded_quantity',0,'scrap_kg',0,'unfinished',6,'remaining_work','Final inspection','reason','Correct counted WIP'),gen_random_uuid());
 perform pg_temp.q_assert((select quantity_available=6 from public.unfinished_lots where id=normal_lot) and (select quantity_available=10 from public.unfinished_lots where id=lot),'normal WIP correction cannot overwrite Quality-origin lot');
 perform pg_temp.q_error(format('select public.supply_command(%L,''material_request'',%L::jsonb,gen_random_uuid())',x.factory_id,jsonb_build_object('item',lot,'item_type','lot','unit','piece','quantity',1)::text),'quality_reserved');
 perform pg_temp.q_error(format('select public.supply_command(%L,''material_request'',%L::jsonb,gen_random_uuid())',x.factory_id,jsonb_build_object('item',lot,'item_type','lot','unit','piece','quantity','0.5','production_item_id',x.item_id)::text),'quality_quantity');
 mr:=public.quality_command(x.factory_id,'request_rework',jsonb_build_object('rejection',q,'lot',lot,'quantity','10'),gen_random_uuid());
 select revision into rev from public.material_requests where id=mr;
 perform public.supply_command(x.factory_id,'material_change',jsonb_build_object('id',mr,'revision',rev,'action','issue'),gen_random_uuid());
 p:=jsonb_build_object('unit_kind','line','production_unit',x.line_id,'item',x.item_id,'technician',x.technician_id,'good',7,'discarded_quantity',3,'scrap_kg',0,'unfinished',0,'input_lot',lot,'input_quantity',10);
 perform pg_temp.q_error(format('select public.record_lean_production(%L,%L::jsonb,gen_random_uuid())',x.factory_id,p::text),'quality_weight');
 perform pg_temp.q_assert((select quantity_available=10 from public.unfinished_lots where id=lot) and (select on_hand=90 from public.finished_goods_balances where factory_id=x.factory_id),'failed rework mass validation rolls back all Good/WIP effects');
 entry:=(public.record_lean_production(x.factory_id,p||jsonb_build_object('scrap_kg','0.75'),gen_random_uuid())->>'id')::uuid;
 perform pg_temp.q_assert((select quantity_available=0 and warehouse_quantity=0 from public.unfinished_lots where id=lot) and (select on_hand=97 from public.finished_goods_balances where factory_id=x.factory_id),'10 rework -> 7 Good + 3 discarded; exact stock conservation');
 perform pg_temp.q_assert((select default_scrap_kg=.75 and actual_scrap_kg=.75 and not weight_overridden from public.quality_rework_records where entry_id=entry) and (select effective_scrap_kg=.75 from public.production_entries where id=entry),'rework failure records kg through Production exactly once');
 perform pg_temp.q_assert((select status='completed' and actual_finish=finish and good_quantity=107 and accepted_good_quantity=97 from public.production_orders where id=x.item_id),'completed history preserved and recovered Good accepted once');
 perform pg_temp.q_assert(private.quality_gap(x.factory_id,q)=3,'rework shortfall remains 3 pieces');
 detail:=public.quality_read(x.factory_id,jsonb_build_object('mode','detail','rejection',q));
 perform pg_temp.q_assert(detail->'rework'->0->>'good'='7' and detail->'rework'->0->>'discarded_quantity'='3' and (detail->'rework'->0->>'scrap_kg')::numeric=.75,'Quality follow-up exposes actual rework Good, discarded units and kg');
 retry:=gen_random_uuid();
 bad:=public.quality_command(x.factory_id,'replacement',jsonb_build_object('rejection',q,'quantity','3'),retry);
 perform pg_temp.q_assert(bad=public.quality_command(x.factory_id,'replacement',jsonb_build_object('rejection',q,'quantity','3'),retry),'corrective task retry creates one item');
 perform pg_temp.q_assert((select replacement_original_item_id=x.item_id and quality_origin_rejection_id=q and target_quantity=3 and status='planned' and line_id is null and start_time is null from public.production_orders where id=bad),'corrective item linked explicitly, never auto-planned');
 perform pg_temp.q_error(format('select public.quality_command(%L,''replacement'',%L::jsonb,gen_random_uuid())',x.factory_id,jsonb_build_object('rejection',q,'quantity','1')::text),'quality_shortfall');
 update public.production_orders set line_id=x.line_id,start_time=now(),expected_finish=now()+interval '1 hour' where id=bad;
 perform public.start_product_item(x.factory_id,bad);
 entry:=(public.record_lean_production(x.factory_id,jsonb_build_object('unit_kind','line','production_unit',x.line_id,'item',bad,'technician',x.technician_id,'good',3,'scrap_kg',0,'discarded_quantity',0,'unfinished',0,'input_quantity',0),gen_random_uuid())->>'id')::uuid;
 perform pg_temp.q_assert((select good_quantity=107 and accepted_good_quantity=97 and fulfillment_good_quantity=100 from public.production_orders where id=x.item_id) and (select on_hand=100 from public.finished_goods_balances where factory_id=x.factory_id),'corrective Good credits once; gross original and physical acceptance stay distinct');
 perform pg_temp.q_assert(private.quality_gap(x.factory_id,q)=0,'corrective Good resolves exact rework shortfall');
 perform public.quality_command(x.factory_id,'resolve',jsonb_build_object('rejection',q),gen_random_uuid());
 perform pg_temp.q_assert((select status='RESOLVED' from public.quality_notifications where id=q),'notification resolves only after recovery');
 perform pg_temp.q_error(format('select public.quality_command(%L,''reverse'',%L::jsonb,gen_random_uuid())',x.factory_id,jsonb_build_object('rejection',q,'physically_present',true,'reason','Already processed stock')::text),'quality_reversal_unavailable');
 insert into public.production_shifts(factory_id,name,name_ar,start_time,end_time,created_by) values(x.factory_id,'Night','ليل','22:00','06:00',x.actor_id) returning id into shift;
 perform pg_temp.q_assert(private.source_shift_date(x.factory_id,shift,'2026-10-10T00:00:00Z')='2026-10-09'::date,'overnight shift uses recorded factory-local business date');
 perform pg_temp.q_assert(private.source_shift_date(x.factory_id,shift,'2026-10-10T09:00:00Z') is null,'out-of-window manual assignment does not invent shift date');
 perform set_config('request.jwt.claim.sub',y.actor_id::text,true);
 perform pg_temp.q_error(format('select public.quality_command(%L,''reject'',%L::jsonb,gen_random_uuid())',x.factory_id,jsonb_build_object('source',s,'quantity',1,'reason',r,'disposition','SCRAP','actual_scrap_kg',1,'physically_identified',true)::text),'permission_denied');
 perform pg_temp.q_error(format('select public.quality_command(%L,''reject'',%L::jsonb,gen_random_uuid())',y.factory_id,jsonb_build_object('source',s,'quantity',1,'reason',r,'disposition','SCRAP','actual_scrap_kg',1,'physically_identified',true)::text),'quality_unavailable');
 set constraints all immediate;
end$$;
rollback;
